// Turn each fetched HTML page into compact, loan-relevant plain text.
//
// Why: a bank page can be 1 MB of HTML but only a few KB of loan terms, and the
// LLM charges by the amount of text it reads. Keeping only lines that talk about
// rates, income, age, credit score and so on also makes the hash steadier:
// rotating banners and footers no longer count as a "changed page".

const MAX_CHARS = 40000;
const MIN_USEFUL_CHARS = 500;

const RELEVANT = /(eligib|income|salar|\bage\b|years|cibil|credit score|interest|rate|%|₹|\brs\.?|lakh|crore|loan amount|tenure|employ|self[- ]employed|business|turnover|vintage|itr|minimum|maximum)/i;

const ENTITIES = {
  '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'",
  '&rsquo;': "'", '&lsquo;': "'", '&rdquo;': '"', '&ldquo;': '"', '&ndash;': '-', '&mdash;': '-',
  '&#8377;': '₹', '&#x20b9;': '₹', '&rupee;': '₹',
};

function htmlToLines(html) {
  const text = html
    .replace(/<(script|style|noscript|svg|head|iframe)[\s\S]*?<\/\1>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<(br|\/p|\/li|\/tr|\/h[1-6]|\/div|\/section|\/table|\/ul|\/ol)\b[^>]*>/gi, '\n')
    .replace(/<(td|th)\b[^>]*>/gi, ' | ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&[#a-z0-9]+;/gi, (e) => ENTITIES[e.toLowerCase()]
      ?? (/^&#\d+;$/.test(e) ? String.fromCharCode(Number(e.slice(2, -1))) : ' '));
  return text.split('\n').map((l) => l.replace(/\s+/g, ' ').replace(/^[\s|]+|[\s|]+$/g, '').trim()).filter(Boolean);
}

// Keep relevant lines plus the line before each (usually the lender or section heading).
function relevantText(lines) {
  const keep = new Set();
  lines.forEach((line, i) => {
    if (RELEVANT.test(line) && line.length < 1000) {
      if (i > 0 && lines[i - 1].length < 120) keep.add(i - 1);
      keep.add(i);
    }
  });
  const out = [];
  for (const i of [...keep].sort((a, b) => a - b)) {
    if (out[out.length - 1] !== lines[i]) out.push(lines[i]); // drop repeated lines
  }
  return out.join('\n').slice(0, MAX_CHARS);
}

const sources = $('Load sources').all().map((i) => i.json);

return $input.all().map((item, index) => {
  const source = sources[item.pairedItem?.item ?? index];
  const html = typeof item.json.html === 'string' ? item.json.html : '';
  const fetchError = item.json.error ? String(item.json.error.message ?? item.json.error).slice(0, 300) : null;
  const text = html ? relevantText(htmlToLines(html)) : '';
  return {
    json: {
      source_site: source.source_site,
      url: source.url,
      previous_hash: source.previous_hash,
      fetch_ok: !fetchError && html.length > 0,
      fetch_error: fetchError,
      html_kb: Math.round(html.length / 1024),
      chars: text.length,
      useful: text.length >= MIN_USEFUL_CHARS,
      text,
    },
  };
});

// One Gemini request per changed page: extract its loan products as JSON.

const MODEL = 'gemini-2.5-flash';
const EMPLOYMENT = ['salaried', 'self_employed', 'business'];

const num = (type = 'NUMBER') => ({ type, nullable: true });
const responseSchema = {
  type: 'ARRAY',
  items: {
    type: 'OBJECT',
    properties: {
      product_name: { type: 'STRING' },
      provider: { type: 'STRING' },
      interest_rate_min: num(),
      interest_rate_max: num(),
      loan_amount_min: num(),
      loan_amount_max: num(),
      min_monthly_income: num(),
      min_credit_score: num('INTEGER'),
      max_credit_score: num('INTEGER'),
      min_age: num('INTEGER'),
      max_age: num('INTEGER'),
      allowed_employment: { type: 'ARRAY', items: { type: 'STRING', enum: EMPLOYMENT }, nullable: true },
      extra_criteria_text: { type: 'STRING', nullable: true },
    },
    required: ['product_name', 'provider'],
  },
};

function instructions(page) {
  return `You extract loan products from the text of an Indian financial web page (a bank or a loan comparison site).

Return one object per distinct personal or business loan product whose terms the page states:
- product_name: lender plus product, e.g. "Yes Bank Personal Loan".
- provider: the lender's name.
- interest_rate_min / interest_rate_max: percent per year.
- loan_amount_min / loan_amount_max, min_monthly_income: INR. Convert "₹15,000" to 15000, "1 lakh" to 100000, "40L" to 4000000, "1 crore" to 10000000.
- min_credit_score / max_credit_score: CIBIL-style 300-900.
- min_age / max_age: years.
- allowed_employment: subset of salaried, self_employed, business; null if the page does not say.
- extra_criteria_text: eligibility rules the fields above cannot hold, as short plain sentences; null if none.

Rules:
- Use only values the page states for that specific product. Do not copy general advice that the page gives about loans in general onto a lender.
- When a rule differs by group (e.g. salaried age 21-60, self-employed 21-65), put the most permissive value in the field (min_age 21, max_age 65) and state the group-specific limits in extra_criteria_text ("Salaried applicants: maximum age 60.").
- Rules about city, employer type, work experience, years in business, turnover or tax returns go in extra_criteria_text.
- Skip a product if the page gives no eligibility terms for it at all (no income, credit score, age or employment rule).
- Return at most 30 products. Return [] if there are none.

Page: ${page.source_site} (${page.url})
---
${page.text}`;
}

return $input.all().map(({ json: page }) => ({
  json: {
    source_site: page.source_site,
    url: page.url,
    text_hash: page.text_hash,
    model: MODEL,
    request_body: {
      contents: [{ role: 'user', parts: [{ text: instructions(page) }] }],
      generationConfig: { temperature: 0, responseMimeType: 'application/json', responseSchema },
    },
  },
}));

// Validate and normalise the products Gemini extracted from each page.
//
// Out-of-range numbers are dropped (set to null), min/max pairs are put in
// order, and a product with no eligibility terms at all is discarded: with no
// rules it would match every user, which would be misleading. If nothing valid
// comes back for a page, the page is marked extract_failed and its stored hash
// is not updated, so the next run tries again.

const EMPLOYMENT = new Set(['salaried', 'self_employed', 'business']);
const RANGES = {
  interest_rate_min: [1, 60], interest_rate_max: [1, 60],
  loan_amount_min: [1000, 1e9], loan_amount_max: [1000, 1e9],
  min_monthly_income: [1000, 1e7],
  min_credit_score: [300, 900], max_credit_score: [300, 900],
  min_age: [18, 100], max_age: [18, 100],
};
const MAX_PRODUCTS = 30;

const sqlText = (value) => (value == null ? 'NULL' : `'${String(value).replace(/'/g, "''")}'`);
const sqlJson = (value) => `'${JSON.stringify(value).replace(/'/g, "''")}'`;

function inRange(value, [lo, hi]) {
  return typeof value === 'number' && Number.isFinite(value) && value >= lo && value <= hi ? value : null;
}

function ordered(p, lo, hi) {
  if (p[lo] != null && p[hi] != null && p[lo] > p[hi]) [p[lo], p[hi]] = [p[hi], p[lo]];
}

function clean(raw) {
  const name = String(raw.product_name ?? '').replace(/\s+/g, ' ').trim();
  if (name.length < 3 || name.length > 150) return null;
  const p = { product_name: name, provider: String(raw.provider ?? '').trim().slice(0, 100) || null };
  for (const [field, range] of Object.entries(RANGES)) p[field] = inRange(raw[field], range);
  ordered(p, 'interest_rate_min', 'interest_rate_max');
  ordered(p, 'loan_amount_min', 'loan_amount_max');
  ordered(p, 'min_credit_score', 'max_credit_score');
  ordered(p, 'min_age', 'max_age');
  const employment = Array.isArray(raw.allowed_employment)
    ? [...new Set(raw.allowed_employment.filter((e) => EMPLOYMENT.has(e)))]
    : [];
  p.allowed_employment = employment.length ? employment : null;
  const extra = String(raw.extra_criteria_text ?? '').trim();
  p.extra_criteria_text = extra ? extra.slice(0, 600) : null;

  const hasEligibility = p.min_monthly_income != null || p.min_credit_score != null
    || p.min_age != null || p.max_age != null || p.allowed_employment != null || p.extra_criteria_text != null;
  return hasEligibility ? p : null;
}

const requests = $('Build extract request').all().map((i) => i.json);

return $input.all().map((item, index) => {
  const req = requests[item.pairedItem?.item ?? index];
  const response = item.json;
  let products = [];
  let error = null;

  const text = response?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (!text) {
    error = String(response?.error?.message ?? response?.error ?? 'no candidates in response').slice(0, 300);
  } else {
    try {
      const parsed = JSON.parse(text);
      if (!Array.isArray(parsed)) throw new Error('response is not an array');
      const seen = new Set();
      for (const raw of parsed) {
        const p = clean(raw ?? {});
        if (!p || seen.has(p.product_name.toLowerCase())) continue;
        seen.add(p.product_name.toLowerCase());
        products.push(p);
      }
      products = products.slice(0, MAX_PRODUCTS);
      if (products.length === 0) error = 'no valid products extracted';
    } catch (e) {
      error = `unparseable LLM output: ${e.message}`;
    }
  }

  const ok = products.length > 0;
  return {
    json: {
      source_site: req.source_site,
      ok,
      product_count: products.length,
      error,
      products_sql: sqlJson(products),
      q_site: sqlText(req.source_site),
      q_url: sqlText(req.url),
      q_hash: sqlText(req.text_hash),
      q_status: sqlText(ok ? 'extracted' : 'extract_failed'),
      q_error: sqlText(error),
      q_ok: ok ? 'TRUE' : 'FALSE',
    },
  };
});

// Pages that did not go to the LLM: unchanged since the last extraction, failed
// to fetch, or had no usable text. Only status fields are updated; the stored
// hash is left alone, so a failed page is retried on the next run.

const sqlText = (value) => (value == null ? 'NULL' : `'${String(value).replace(/'/g, "''")}'`);

return $input.all().map(({ json: s }) => {
  let status = 'unchanged';
  let error = null;
  if (!s.fetch_ok) {
    status = 'fetch_failed';
    error = s.fetch_error;
  } else if (!s.useful) {
    status = 'no_content';
    error = `only ${s.chars} characters of loan-related text`;
  }
  return {
    json: {
      source_site: s.source_site,
      status,
      q_site: sqlText(s.source_site),
      q_status: sqlText(status),
      q_error: sqlText(error),
    },
  };
});

parameters.query:
=UPDATE crawl_sources
    SET last_crawled_at = now(), last_status = {{ $json.q_status }}, last_error = {{ $json.q_error }}
  WHERE source_site = {{ $json.q_site }}
RETURNING source_site, last_status;

WITH crawled AS (
  SELECT count(*) AS n FROM loan_products WHERE source_site <> 'seed' AND is_active
), upd AS (
  UPDATE loan_products SET is_active = ((SELECT n FROM crawled) < 5)
   WHERE source_site = 'seed'
  RETURNING is_active
)
SELECT (SELECT n FROM crawled)::int AS crawled_active_products,
       COALESCE(bool_or(is_active), FALSE) AS seed_products_active
  FROM upd;
